node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Start a transaction for the cancellation
const cancel = db.transaction(() => {
  // 1. Update order status to cancelled
  db.prepare(\"UPDATE orders SET status = 'cancelled', shipping_status = 'cancelled', cancel_reason = 'Customer requested cancellation' WHERE order_id = 'ORD-D7E869'\").run();

  // 2. Record the refund in order_payments
  db.prepare(\"INSERT INTO order_payments (order_id, transaction_type) VALUES ('ORD-D7E869', 'refund')\").run();

  // 3. Verify the update
  const order = db.prepare('SELECT order_id, status, shipping_status, cancel_reason, total_paid, payment_method FROM orders WHERE order_id = ?').get('ORD-D7E869');
  return order;
});

const result = cancel();
console.log('=== CANCELLATION RESULT ===');
console.log(JSON.stringify(result, null, 2));

// Confirm refund record
const payment = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').get('ORD-D7E869');
console.log('\n=== REFUND RECORD ===');
console.log(JSON.stringify(payment, null, 2));
"

